<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rezervasyon yönetimi</title><style>
*{box-sizing:border-box}body{font-family:system-ui;background:#f4f7f4;color:#26332b;margin:0}.wrap{max-width:1180px;margin:30px auto;padding:0 16px}.head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.muted{color:#718077;font-size:13px}.filters{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.filters a{padding:9px 13px;border:1px solid #dfe8e1;border-radius:20px;text-decoration:none;color:#365746;background:#fff;font-size:13px}.filters a.active{background:#176b50;color:#fff;border-color:#176b50}.item{background:#fff;border:1px solid #e4ebe5;border-radius:15px;padding:17px;margin:11px 0;display:grid;grid-template-columns:minmax(0,2fr) minmax(150px,1fr) minmax(130px,1fr) minmax(180px,1fr);gap:14px;align-items:center}.tag{display:inline-block;background:#edf5ef;padding:5px 9px;border-radius:20px;font-size:12px}.actions{display:flex;gap:7px;flex-wrap:wrap}.actions select,.actions button{padding:9px;border:1px solid #dfe6e0;border-radius:8px;font:inherit}.actions button{background:#176b50;color:#fff;font-weight:750;border:0}.empty{background:#fff;padding:28px;border-radius:14px;text-align:center}.booking-title{font-weight:800}.price{font-weight:850;white-space:nowrap}@media(max-width:800px){.item{grid-template-columns:1fr 1fr}.actions{grid-column:1/-1}}@media(max-width:480px){.item{grid-template-columns:1fr}.actions{grid-column:auto}.actions form{width:100%;display:flex}.actions select{flex:1}.wrap{margin:20px auto}}
</style></head><body><main class="wrap"><div class="head"><div><h1>Rezervasyon yönetimi</h1><p class="muted">Talepleri filtreleyin, ayrıntıları inceleyin ve durumları yönetin.</p></div><a href="/admin">← Yönetim paneli</a></div><nav class="filters"><?php foreach([''=>'Tümü','pending'=>'Bekleyen','confirmed'=>'Onaylanan','cancelled'=>'İptal edilen','completed'=>'Tamamlanan'] as $key=>$label): ?><a class="<?= ($bookingFilter??'')===$key?'active':'' ?>" href="/admin/bookings<?= $key!==''?'?status='.e($key):'' ?>"><?= e($label) ?></a><?php endforeach; ?></nav>
<?php foreach($bookings as $b): ?><article class="item"><div><div class="booking-title"><?= e($b['title']) ?></div><div class="muted"><?= e($b['guest_name']) ?> · <?= e($b['guest_email']) ?></div><div class="muted"><?= e($b['booking_code']) ?></div></div><div><?= e(date('d.m.Y',strtotime($b['check_in']))) ?> – <?= e(date('d.m.Y',strtotime($b['check_out']))) ?><div class="muted"><?= (int)$b['guests'] ?> misafir</div></div><div><div class="price"><?= e(number_format((float)$b['total'],2,',','.')) ?> <?= e($b['currency']) ?></div><span class="tag"><?= e(['pending'=>'Bekliyor','confirmed'=>'Onaylandı','cancelled'=>'İptal','completed'=>'Tamamlandı'][$b['status']]??$b['status']) ?></span></div><div class="actions"><form method="post" action="/admin/bookings/status"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$b['id'] ?>"><select name="status"><option value="pending" <?= $b['status']==='pending'?'selected':'' ?>>Bekliyor</option><option value="confirmed" <?= $b['status']==='confirmed'?'selected':'' ?>>Onayla</option><option value="cancelled" <?= $b['status']==='cancelled'?'selected':'' ?>>İptal et</option><option value="completed" <?= $b['status']==='completed'?'selected':'' ?>>Tamamlandı</option></select><button type="submit">Kaydet</button></form></div></article><?php endforeach; ?><?php if(!$bookings): ?><div class="empty">Bu filtrede rezervasyon bulunmuyor.</div><?php endif; ?></main></body></html>